add('rd-c21-t3-past-discoveries',3,3,'Rethinking the Past · 发现怎样改变既有认识',[69],[71,72],ps(69,4,7),['multiple-choice','matching-sentence-endings'],[
 q(27,'What is the writer doing in the second paragraph?','A','Two things stand out to me. One is ... advanced behaviours ... much further back ... And the other ... misunderstood gender roles','作者归纳两项认识变化，不是在罗列考古学家的争议；second paragraph指原第2段。',MC,['A. pinpointing some key changes in our understanding of prehistory','B. outlining some aspects of prehistory which are still poorly understood','C. summarising some attitudes towards recent archaeological revelations','D. giving an overview of some current disagreements among archaeologists']),
 q(31,'The findings at Kalambo Falls revealed that','E',"buried logs ... shaped with stone tools so that they interlocked ... 476,000 years old ... before our species",'石器加工并互锁的木材早于现代人，支撑其他物种也能进行复杂制作；不是说现代人提前出现。',END,endings),
 q(32,'Evidence from high-altitude regions suggests that','F','the Denisovans lived on the frozen heights ... 200,000 years ago','extinct hominins先在严寒高地生活，对应other species在Homo sapiens之前适应恶劣环境。',END,endings)
],{'structure':['开篇交代发现很多、共同线索难找；第二段明确两条总体变化；第三段以建筑和高地定居举证。','第31与32题都与旧时间线被推翻有关，但分别是加工能力和环境适应，不能看到before就选同一项。'],'phrases':['come thick and fast：接连大量出现。','as opposed to：对比修正前后的年龄估计。','upending the old notion：推翻旧看法，不是仅增加无关事实。'],'sentences':["This would be unsurprising if they weren't 476,000 years old. → 虚拟条件凸显年代是发现惊人之处。",'Two things stand out to me. One ... And the other ... → 平行结构直接给第27题的篇章功能。']},'原第1–3段连续裁切；第27题的second paragraph仍指原文第2段。句尾匹配保留A–F完整选项，不删干扰项。')

