add('rd-c21-t4-hyacinth-biogas',4,1,'Water hyacinth · 沼气流程、收益与价格障碍',[83],[85],ps(83,2,7),['flow-chart-completion','note-completion'],[
 q(8,'First, place water hyacinth together with some ______ into a digester','cow dung','a mix of water hyacinth and cow dung into biogas for cooking','本村digester混入cow dung，两词；不能因前文另有chicken manure实验就换材料。',FLOW),
 q(9,'Leave the mixture until the ______ is completed','fermentation / fermentation process','over the next 20 to 30 days, it goes through a fermentation process and breaks down','题面until ... completed对应经过发酵阶段；官方答案接受fermentation或fermentation process，均不超过两词。',FLOW),
 q(10,'Capture the gas emitted by the digester and use ______ to transport it to individual homes','pipes','the clean burning gas is passed through pipes to the point of use','填运送管道pipes，不填终点homes或燃气本身。流程终点还包括做饭和净水。',FLOW),
 q(11,'no need for them to spend so much ______ collecting fuel','time',"they don't have to devote a lot of time every day to gathering firewood",'spend ... collecting与devote ... to gathering对应；空格是节省的time。',NOTE),
 q(12,'they can focus on different tasks that bring in ______','money',"they're able to make more money for their families from other enterprises",'different tasks对应other enterprises；bring in对应make money。',NOTE),
 q(13,'the ______ of the digesters is beyond the reach of most villages','price',"unless the price of the machines drops ... most communities will never be able to afford any",'beyond the reach意为负担不起，与unless price drops的条件对应；题目一词，不能填750 dollars。',NOTE)
],{'structure':['村庄引入设备→混合发酵与输气→女性时间收入和健康收益→仍待研究及价格限制。','流程图按原箭头First→Leave→Capture→Use填写，收益/障碍笔记另按段意定位。'],'phrases':['a two-for-one solution：同时应对水草与柴火依赖。','breaks down, giving off gas：分解并释放气体。','beyond the reach：难以负担，在本题是价格而非地理距离。'],'sentences':['The mixture goes in one end ... and ... goes through a fermentation process and breaks down, giving off gas ... → 主干依次说明进入、发酵、分解；giving off补充结果。',"But unless the price of the machines drops ... most communities will never be able to afford any. → unless提出普及的必要条件，不能把目前局部成功扩成处处买得起。"]},'原第6–10段连续裁切。原流程最后一步为“Then use the gas for cooking as well as making water fit for human consumption”，与片段purifying water对应，未另造步骤。')

delhi_options=['A. basic outlook','B. employment opportunities','C. wealthy visitors','D. distant country','E. primary objective','F. similar advantages','G. thriving economy','H. nearby district','I. dense population','J. new immigrants']
add('rd-c21-t4-multilingual-background',4,2,'Multilingualism · 迁移背景与研究目标',[86],[88],ps(86,5,9),['summary-completion-options','yes-no-not-given'],[
 q(14,'The city of Delhi has a ______ and as you walk through its streets you hear people speaking a variety of languages.','I','The crowded and bustling streets of Delhi teem with life ... more than 20 million people','crowded与2000多万人对应dense population；不是只因bustling就选thriving economy。',SUM,delhi_options),
 q(15,'Some of them have spent their entire life in Delhi, while others are ______.','J','many millions more have recently made India’s capital their home, having moved from ...','recently迁入与new immigrants对应；不等于wealthy visitors短期游客。',SUM,delhi_options),
 q(16,'Whether they have come from a ______ or have travelled from the other side of India,','H','having moved from surrounding neighbourhoods, cities and states or across the country','surrounding neighbourhoods对应nearby district，与other side形成近/远对照；原文不是移自国外。',SUM,delhi_options),
 q(17,'they have all come in search of things such as improved ______.','B','often in the hope of gaining better jobs and a better life','better jobs对应employment opportunities；不要凭“更好生活”添富游客身份。',SUM,delhi_options),
 q(18,'The ______ of the research is to discover why multilingual Indian schoolchildren do not experience','E','The overriding aim of the four-year project ... is to find out why','overriding aim同义于primary objective，句法也需要单数研究目标。',SUM,delhi_options),
 q(19,'______ to those that multilingual schoolchildren in Europe experience.','F','the many benefits ... observed in schools in Europe ... do not apply to many of India’s schoolchildren','benefits对应advantages；研究问为何并未获得相似收益。',SUM,delhi_options),
 q(20,'Ten-year-old Indian schoolchildren tend to perform better in literacy tests than in numeracy tests.','NO','over 50% ... cannot read ... and just under 50% ... cannot solve ... subtraction','识字不达标超过50%，计算不达标略低于50%，方向与better in literacy相反；比较的是不能完成的比例。',YN),
 q(21,'Tsimpli had problems convincing some female students to take part in the study.','NOT GIVEN','low educational achievement ... dropping out of school ... disproportionately affecting female students','女生受退学影响更多不是难以说服参加研究；全文没有recruitment问题。',YN),
 q(22,'Tsimpli and her team wanted to know if there is a connection between poor academic performance and being taught in an unfamiliar language.','YES','investigating whether these low learning outcomes could be caused by ... language ... taught in often differs from ... used at home','研究的问题正是低学习表现与教学/家庭语言不一致是否有关。',YN)
],{'structure':['人口迁移造成多语环境→项目目标→学习表现数据→研究教学语言与家庭语言之间的落差。','摘要选词看同义替换也看搭配：primary objective of the research、similar advantages to those。'],'phrases':['the overriding aim：首要目标。','let alone：更不用说，用来递进语言数量。','disproportionately affecting：影响不成比例，不自动说明调查招募困难。'],'sentences':['over 50% ... cannot read ... and just under 50% ... cannot solve ... → 两个否定能力比例并列，解第20题须把“不能”保留。','Tsimpli and her colleagues are investigating whether ... → whether引导研究的问题，不能把尚在研究的假说说成已经证明的原因。']},'原第1–4段连续裁切；词表A–J保留原题所有选项，含OCR漏掉的I已按原选项和答案页恢复。NG21已核对完整文章。')

add('rd-c21-t4-multilingual-findings',4,2,'Multilingualism · 教学语言与出人意料的结果',[87],[88,89],ps(87,1,5),['yes-no-not-given','multiple-choice'],[
 q(23,'The researchers have decided against investigating the impact teaching methodology may have on learning outcomes.','NO','They intend to look not only at test results, but also ... the teaching practices themselves','intend to investigate practices直接反驳decided against investigating methodology。',YN),
 q(24,'What point does the writer make about primary schools in India in the sixth paragraph?','C','English, may hold back those children who have little familiarity with, or exposure to, the language','不熟悉教学用英语可能进一步拖住贫困儿童；不是说动机能使英语更容易学。',MC,['A. Exposure to English outside of school is of limited benefit.','B. Children learn English more easily when they are well motivated.','C. Poor children may be disadvantaged further by being instructed in English.','D. There is little consistency across schools with regard to instruction in English.']),
 q(25,"What is Tsimpli suggesting when she uses the phrase 'that ship has sailed'?",'D',"We are not suggesting that English be withdrawn - that ship has sailed",'紧贴前半句be withdrawn理解：完全撤回英语已不现实。B是后文改进方向，却不是该习语所指。',MC,['A. The findings of the report may be of little help to some Indian schoolchildren.','B. Instruction in English could be better adapted to the needs of schoolchildren.','C. Schools have had limited success in teaching English as a separate subject.','D. It is too late to remove English completely as a language of instruction in schools.']),
 q(26,'In the eighth paragraph, what do we learn has surprised researchers?','D','an unanticipated finding ... children from slum backgrounds do not seem to lag behind ... and in some cases outperform them','unanticipated锁定意外发现：贫民窟儿童读写算并未落后，有时更好；general intelligence相同只是前面的背景。',MC,['A. Boys and girls from low socio-economic groups have similar general intelligence levels.','B. The age at which children move into a slum does not affect their academic performance.','C. Slum children and children from other urban poor backgrounds have similar life experiences.','D. The literacy and numeracy skills of slum children are not lower than those of children from other urban poor backgrounds.'])
],{'structure':['准备复测并查教学方法→英语媒介潜在阻碍→调整建议→贫民窟儿童技能的意外结果。','第24题看研究发现，第25题限定习语所指，第26题用unanticipated定位“惊讶”而非所有被提及事实。'],'phrases':['the medium of instruction：教其他科目所用语言，区别作为一门语言课。','that ship has sailed：相关机会已经过去，不宜按船的字面理解。','lag behind / outperform：落后于/表现胜过，注意not与in some cases。'],'sentences':['English can still be used, but perhaps not as the medium of instruction ... It could ... be one of the subjects ... → 不是取消英语，而是区分教学媒介与课程科目。','While the preliminary results show ... an unanticipated finding has been ... → While从句提供对照背景，主句才是第26题问的意外发现。']},'原第5–8段连续裁切；题面sixth/eighth paragraph分别对应本片段第2/4段。保留may、might、preliminary等不确定表达。')

